import { desc } from 'drizzle-orm';
import {
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core';
import type {
  VariantHistoryManifest,
  VariantHistoryStatus,
} from '@rivet/core/types/variant-history';

export const metadataState = sqliteTable('metadata_state', {
  key: text().primaryKey(),
  value: text().notNull(),
  updatedAt: text('updated_at').notNull(),
});

export const variants = sqliteTable(
  'variants',
  {
    sessionId: text('session_id').notNull(),
    variantId: text('variant_id').notNull(),
    label: text().notNull(),
    brief: text().notNull(),
    sessionPrompt: text('session_prompt').notNull(),
    runLabel: text('run_label'),
    status: text().$type<VariantHistoryStatus>().notNull(),
    createdAt: text('created_at').notNull(),
    statusChangedAt: text('status_changed_at').notNull(),
    hasTree: integer('has_tree', { mode: 'boolean' }).notNull(),
    serveKind:
      text('serve_kind').$type<
        NonNullable<VariantHistoryManifest['serve']>['kind']
      >(),
    hasStaticPreview: integer('has_static_preview', {
      mode: 'boolean',
    }).notNull(),
    manifestMtimeMs: integer('manifest_mtime_ms').notNull(),
    manifest: text('manifest_json', { mode: 'json' })
      .$type<VariantHistoryManifest>()
      .notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.sessionId, table.variantId] }),
    index('variants_created_at_idx').on(desc(table.createdAt)),
    index('variants_status_idx').on(table.status),
  ],
);
